# Generated by tools/prepare_public_core.py; see CORE_PROVENANCE.json.
import re
from datetime import date
from copy import deepcopy
from .domain import FACILITY, require

BASE_URL = (
    "https://rsv.shisetsu.city.katsushika.lg.jp"
    "/katsushika/web/"
)

TIMES = [
    "08:00-10:00",
    "10:00-12:00",
    "12:00-14:00",
    "14:00-16:00",
    "16:00-18:00",
    "18:30-20:30",
    "20:30-22:30",
]

def get_status(src):

    filename = src.split("?")[0].rsplit("/", 1)[-1].lower()

    if filename == "lw_emptybs.gif":
        return "AVAILABLE"

    if filename == "lw_210.gif":
        return "GENERAL_RESERVED"

    return "UNKNOWN"

def read_availability(page):

    table = page.locator("table.akitablelist").first

    table.wait_for(
        state="visible",
        timeout=15000
    )

    rows = table.locator("tr")

    if rows.count() != 3:
        raise RuntimeError("Cau truc bang khong dung!")

    # Lay ngay
    header = rows.nth(0).inner_text()

    match = re.search(
        r"(\d{4})年\s*(\d{1,2})月\s*(\d{1,2})日",
        header
    )

    if not match:
        raise RuntimeError("Khong doc duoc ngay!")

    year, month, day = map(int, match.groups())

    current_date = date(year, month, day).isoformat()

    slots = []

    # Doc san A va B
    for row_index in (1, 2):

        row = rows.nth(row_index)

        court = row.locator("th").first.inner_text().strip()

        images = row.locator("td img")

        if images.count() != len(TIMES):
            raise RuntimeError(
                f"So khung gio khong dung: {court}"
            )

        for index, time in enumerate(TIMES):

            src = images.nth(index).get_attribute("src") or ""

            status = get_status(src)

            slots.append({
                "court": court,
                "time": time,
                "status": status
            })

    return {
        "date": current_date,
        "slots": slots
    }

def open_availability_page(page):

    page.goto(
        BASE_URL,
        wait_until="domcontentloaded"
    )

    page.get_by_role("link").filter(
        has_text="施設を利用するにはこちらをクリックして下さい。"
    ).click()

    page.get_by_role(
        "link", name="施設の空き状況"
    ).click()

    page.get_by_role(
        "link", name="複合検索"
    ).click()

    page.get_by_role(
        "link", name="館"
    ).click()

    page.get_by_role(
        "link", name=FACILITY
    ).click()

    page.get_by_role(
        "link", name="検索を開始する"
    ).click()

    page.locator(
        "table.akitablelist"
    ).first.wait_for(state="visible")

ICON_STATUS = {
    "lw_emptybs.gif": "AVAILABLE",
    "lw_210.gif": "GENERAL_RESERVED",  # mapping PoC02 đã PASS
    "lw_finishs.gif": "GENERAL_RESERVED",  # mẫu trong Help
    "lw_211.gif": "TOURNAMENT_RESERVED",  # 大会予約
    "lw_212.gif": "EVENT_RESERVED",  # 行事予約
    "lw_213.gif": "OTHER_RESERVED",  # その他予約
    "lw_214.gif": "COMMUNITY_RESERVED",  # 地元開放予約
    "lw_closes.gif": "CLOSED",
    "lw_keeps.gif": "MAINTENANCE",
    "lw_akuten.gif": "BAD_WEATHER",
    "lw_kikangais.gif": "OUTSIDE_ACCEPTANCE_PERIOD",
    "lw_900.gif": "UNSELECTABLE",
    "lw_notime.gif": "UNBOOKABLE_TIME",
}

def icon_status(source):
    if not isinstance(source, str):
        return "UNKNOWN"
    base = source.split("?", 1)[0].split("#", 1)[0].rsplit("/", 1)[-1].lower()
    return ICON_STATUS.get(base, "UNKNOWN")

def map_day_icons(page, data):
    """Bổ sung status sau reader PoC02; chụp cùng ngày/thứ tự, chỉ đọc bảng.

    Không đọc URL động, form value, cookie hay storage. Chỉ trả basename icon.
    """
    metadata = page.locator("table.akitablelist").first.evaluate(r"""table => {
        const match = table.rows[0]?.innerText.match(/(\d{4})年\s*(\d{1,2})月\s*(\d{1,2})日/);
        return {date:match ? `${match[1]}-${match[2].padStart(2,'0')}-${match[3].padStart(2,'0')}` : null,
            icons:[...table.querySelectorAll('td img')].map(image =>
                (image.getAttribute('src') || '').split('?')[0].split('#')[0].split('/').pop().toLowerCase())};
    }""")
    require(isinstance(metadata, dict) and metadata.get("date") == data["date"], "ICON_DATE_MISMATCH")
    icons = metadata.get("icons")
    require(isinstance(icons, list) and len(icons) == len(data["slots"]) == 14, "ICON_COUNT_MISMATCH")
    result = deepcopy(data)
    for row, icon in zip(result["slots"], icons, strict=True):
        row["status"] = icon_status(icon)
    return result
